	if err != nil {
		return nil, err
	}
	defer f.Close() // This will be called at the end of the function, but not earlier
	return f, nil
}

func writeToFile(f *os.File, data string) error {
	_, err := f.WriteString(data)
	if err != nil {
		return err
	}
	return nil
}

